	// Restore stderr and read captured output
	w.Close()
	os.Stderr = oldStderr
	captured, err := io.ReadAll(r)
	if err != nil {
		t.Fatal(err)
	}

	// Assert the error message was printed to stderr
	expected := "zerolog: could not write event: write error\n"
