	// Allow extra-verbose logs.
	SetGlobalLevel(TraceLevel - 1)
	log := New(lw).Level(TraceLevel - 1)

	// Catch the panic from log.Panic().Msg("1")
	defer func() {
		if r := recover(); r == nil {
			t.Error("expected panic from log.Panic()")
		}
	}()
	log.Panic().Msg("1")
